const test = require('node:test');
const assert = require('node:assert/strict');
const { timelinePage } = require('../timeline.cjs');
const rows = Object.freeze([
  Object.freeze({minute:40,entryId:1}),
  Object.freeze({minute:40,entryId:2}),
  Object.freeze({minute:40,entryId:10}),
  Object.freeze({minute:41,entryId:1}),
  Object.freeze({minute:43,entryId:3})
]);
test('exclusive numeric pair cursor', () => {
  assert.deepEqual(timelinePage(rows, {minute:40,entryId:1}, 1), {
    items:[rows[1]], nextCursor:{minute:40,entryId:2}
  });
  assert.deepEqual(timelinePage(rows, {minute:40,entryId:3}, 2), {
    items:[rows[2],rows[3]], nextCursor:{minute:41,entryId:1}
  });
  assert.deepEqual(timelinePage(rows, {minute:40,entryId:10}, 3), {
    items:[rows[3],rows[4]], nextCursor:null
  });
});
test('successive pages neither skip nor repeat', () => {
  let cursor = null;
  const seen = [];
  for (let attempt = 0; attempt < 6; attempt++) {
    const page = timelinePage(rows, cursor, 2);
    seen.push(...page.items);
    cursor = page.nextCursor;
    if (cursor === null) break;
  }
  assert.deepEqual(seen, rows);
  assert.deepEqual(timelinePage([], null, 2), {items:[],nextCursor:null});
  assert.deepEqual(timelinePage(rows, {minute:43,entryId:3}, 2), {items:[],nextCursor:null});
  assert.deepEqual(timelinePage(rows, null, 5), {items:rows,nextCursor:null});
});

test('preserves record fields and does not mutate a mutable input or cursor', () => {
  const input = [
    {minute:5,entryId:1,label:'opened'},
    {minute:5,entryId:8,label:'accepted',meta:{owner:'Lin'}},
    {minute:6,entryId:2,label:'closed'}
  ];
  const cursor = {minute:5,entryId:4};
  const before = structuredClone(input), prior = {...cursor};
  assert.deepEqual(timelinePage(input, cursor, 1), {
    items:[before[1]],nextCursor:{minute:5,entryId:8}
  });
  assert.deepEqual(input, before);
  assert.deepEqual(cursor, prior);
});

