function timelinePage(rows, cursor, limit) {
  const remaining = cursor === null ? rows : rows.filter(row =>
    row.minute > cursor.minute ||
    (row.minute === cursor.minute && row.entryId > cursor.entryId));
  const items = remaining.slice(0, limit);
  const last = items[items.length - 1];
  const nextCursor = remaining.length > limit
    ? { minute: last.minute, entryId: last.entryId }
    : null;
  return { items, nextCursor };
}
module.exports = { timelinePage };

